<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\{BelongsTo,HasMany}; class DeliveryNote extends Model {protected $fillable=['delivery_number','sales_order_id','warehouse_id','status','delivery_date','notes','created_by']; protected $casts=['delivery_date'=>'date']; public function order():BelongsTo{return $this->belongsTo(SalesOrder::class,'sales_order_id');} public function warehouse():BelongsTo{return $this->belongsTo(Warehouse::class);} public function creator():BelongsTo{return $this->belongsTo(User::class,'created_by');} public function lines():HasMany{return $this->hasMany(DeliveryNoteLine::class);} }